<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import M9Sidebar from '../components/M9Sidebar.vue'
import {movieArtwork} from '../services/movieArtwork'
import {ISO2_TO_ISO3} from '../lib/globe/iso2to3.js'
import {countryName} from '../lib/globe/countryDisplay.js'
const route=useRoute(),router=useRouter(),expanded=ref(localStorage.getItem('mi2_nav_expanded')==='true')
const movie=ref<any>(null),state=ref<any>({}),recommendations=ref<any[]>([]),busy=ref(true),saving=ref(false),error=ref(''),actionError=ref(''),notice=ref(''),rating=ref('4'),posterFailed=ref(false),backdropFailed=ref(false),behaviorReady=ref(false),countries=ref<string[]>([])
const id=computed(()=>route.hash.slice(7)),art=computed(()=>movieArtwork[id.value])
const mediaUrl=(p?:string)=>p&&p.startsWith('http')?'/api/media/poster?u='+encodeURIComponent(p):p
const asset=computed(()=>{const list=movie.value?.assets||[];const pick=(type:string)=>list.find((a:any)=>a.asset_type===type&&a.is_primary)||list.find((a:any)=>a.asset_type===type);return {poster:mediaUrl(pick('poster')?.source_path)||art.value?.poster,backdrop:mediaUrl(pick('backdrop')?.source_path)||art.value?.backdrop}})
const photoFailures=ref<Record<string,boolean>>({})
function photo(c:any){
 const path=c.profile_path
 if(typeof path!=='string'||!/^\/[A-Za-z0-9_-]+\.(?:jpg|jpeg|png|webp)$/i.test(path))return ''
 return '/api/media/poster?u='+encodeURIComponent('https://image.tmdb.org/t/p/w185'+path)
}
const photoKey=(c:any)=>String(c.person_id)+':'+String(c.profile_path)
const CAST_PREVIEW_LIMIT=9
const visibleCredits=computed(()=>[...directors.value,...cast.value].slice(0,CAST_PREVIEW_LIMIT))
const missingPhotos=computed(()=>visibleCredits.value.filter(c=>!photo(c)||photoFailures.value[photoKey(c)]).length)

const tmdbId=computed(()=>((movie.value?.external_ids||[]).find((x:any)=>x.source==='tmdb')||{}).external_id||'')
const tmdbCastUrl=computed(()=>tmdbId.value?`https://www.themoviedb.org/movie/${tmdbId.value}/cast`:'')
const posterFallback=computed(()=>mediaUrl((movie.value?.assets||[]).find((a:any)=>a.asset_type==='poster'&&a.source==='tmdb')?.source_path))
function onPosterError(e:Event){const img=e.target as HTMLImageElement;const fb=posterFallback.value;if(fb&&!img.dataset.fb){img.dataset.fb='1';img.src=fb}else{posterFailed.value=true}}
function preferredCredits(rows:any[]){const official=rows.filter(c=>c.source==='tmdb');return official.length?official:rows}
const directors=computed(()=>preferredCredits((movie.value?.credits||[]).filter((c:any)=>c.role_type==='crew'&&c.job==='Director')))
const cast=computed(()=>preferredCredits((movie.value?.credits||[]).filter((c:any)=>c.role_type==='cast'))),genreText=computed(()=>(movie.value?.genres||[]).map((g:any)=>g.name_zh).join(' / ')),sourceRatings=computed(()=>movie.value?.ratings||[])
const actions=[{kind:'want',name:'想看',path:'M12 5v14M5 12h14'},{kind:'watched',name:'已看',path:'m5 12 4 4L19 6'},{kind:'favorite',name:'收藏',path:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z'},{kind:'not_interested',name:'不感兴趣',path:'M5 5l14 14M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'}]
let controller:AbortController|undefined,serial=0
async function api(path:string,signal?:AbortSignal){const r=await fetch('/api/catalog/'+path,{credentials:'same-origin',signal});if(!r.ok)throw new Error(r.status===404?'没有找到这部电影。':r.status===401?'登录已失效，请重新登录。':'资料暂时无法读取，请重试。');return(await r.json()).data}
async function readBehavior(){const target=id.value;const b=await api('behavior');if(target!==id.value)return;state.value=b.state[target]||{};rating.value=String(state.value.rating??4);behaviorReady.value=true}
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal,n=++serial;busy.value=true;error.value='';movie.value=null;notice.value='';actionError.value='';posterFailed.value=false;backdropFailed.value=false;photoFailures.value={};behaviorReady.value=false;state.value={};recommendations.value=[];countries.value=[];try{if(!/^[1-9]\d*$/.test(id.value))throw new Error('电影编号无效。');const data=await api('movies/'+id.value,signal);if(n!==serial)return;if(data.credits_has_more){const all:any[]=[];let offset=0;while(true){const page=await api('movies/'+id.value+'/credits?limit=100&offset='+offset,signal);if(n!==serial)return;all.push(...page.items);if(!page.has_more)break;if(!Number.isSafeInteger(page.next_offset)||page.next_offset<=offset)throw new Error('演职员分页异常，请重试。');offset=page.next_offset}data.credits=all}movie.value=data;document.title=(data.title||'电影详情')+' · MovieInsight';try{await readBehavior()}catch{actionError.value='个人状态读取失败，请刷新状态后操作。'}try{const cc=await api('production-countries',signal);if(n===serial){const row=(cc.items||[]).find((x:any)=>String(x.movie_id)===id.value);countries.value=((row?.countries)||[]).map((c:any)=>(ISO2_TO_ISO3 as Record<string,string>)[c.iso2]).filter(Boolean)}}catch{}try{const r=await api('recommendations?limit=6',signal);if(n===serial)recommendations.value=r.items.filter((m:any)=>String(m.movie_id)!==id.value).slice(0,3)}catch{}}catch(e){if(!signal.aborted&&n===serial)error.value=(e as Error).message}finally{if(n===serial)busy.value=false}}
watch(id,load,{immediate:true})
function back(){if(route.query.from==='recommendations'){const query={...route.query};delete query.from;router.push({path:'/recommendations',query});return}if(route.query.from==='admin'){router.push('/admin');return}if(route.query.from==='home'){router.push('/home');return}if(route.query.from==='behavior'){router.push({path:'/movies',hash:'#behavior',query:{view:route.query.view}});return}const query={...route.query};delete query.from;router.push({path:'/movies',query,hash:''})}
function openMovie(mid:number){router.push({path:'/movies',query:route.query,hash:'#movie/'+mid})}
async function refreshState(){try{await readBehavior();actionError.value='';notice.value='状态已刷新'}catch{actionError.value='状态仍无法确认，请稍后重试。'}}
async function act(kind:string,undo=false,value:number|null=null){if(saving.value||!behaviorReady.value)return;const target=id.value;saving.value=true;notice.value='';actionError.value='';try{const csrf=await fetch('/api/v1/auth/csrf',{credentials:'same-origin'});if(!csrf.ok)throw new Error('登录已失效，请重新登录。');const token=(await csrf.json()).data.csrf_token;const r=await fetch('/api/catalog/behavior',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify({event_id:crypto.randomUUID(),movie_id:Number(target),kind,action:undo?'undo':'set',value,time:new Date().toISOString(),source:'USER_ACTION'})});if(!r.ok)throw new Error(r.status===409?'行为状态冲突，请先撤销已看或不感兴趣，再操作。':'保存结果未确认，请刷新状态；不会自动重复提交。');if(target===id.value){await readBehavior();notice.value=undo?'已撤销':'已保存';window.dispatchEvent(new Event('mi2-behavior-changed'))}}catch(e){if(target===id.value){actionError.value=(e as Error).message;behaviorReady.value=false}}finally{saving.value=false}}
onBeforeUnmount(()=>controller?.abort())
</script>
<template>
<div class="detail-shell" :style="{'--nav-width':expanded?'280px':'52.5px'}"><M9Sidebar @expanded-change="expanded=$event"/><div class="detail-content"><div class="container breadcrumb"><button @click="back">{{route.query.from==='recommendations'?'返回推荐频道':route.query.from==='home'?'返回影院首页':route.query.from==='admin'?'返回数据驾驶舱':'返回电影库'}}</button><span class="divider">›</span><strong>{{movie?.title||'电影详情'}}</strong></div>
<div v-if="busy" role="status" class="loading">正在读取电影资料…</div><div v-else-if="error" role="alert" class="loading"><h1>暂时无法展示</h1><p>{{error}}</p><button class="btn" @click="load">重试</button></div>
<template v-else-if="movie"><section class="hero" aria-labelledby="movie-title"><img v-if="asset.backdrop&&!backdropFailed" class="backdrop-art" :src="asset.backdrop" alt="" @error="backdropFailed=true"/><div class="container hero-grid"><div class="poster"><img v-if="asset.poster&&!posterFailed" :src="asset.poster" :alt="movie.title+'海报'" @error="onPosterError"/><span v-else>{{movie.title}}</span></div><div class="hero-copy"><h1 id="movie-title">{{movie.title}}</h1><div class="en">{{movie.original_title||''}}</div><div class="meta"><span>{{movie.release_year||'年份未知'}}</span><span class="sep">·</span><span>{{movie.runtime_minutes?movie.runtime_minutes+' 分钟':'片长未知'}}</span><span v-for="g in movie.genres" :key="g.genre_id" class="genre">{{g.name_zh}}</span></div><p class="hero-intro">{{movie.overview||'暂无剧情简介。'}}</p><div class="cta"><button v-for="a in actions" :key="a.kind" class="btn" :class="{primary:a.kind==='want',danger:a.kind==='not_interested'}" :disabled="saving||!behaviorReady" :aria-pressed="!!state[a.kind]" @click="act(a.kind,!!state[a.kind])"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path :d="a.path"/></svg>{{state[a.kind]?'撤销':''}}{{a.name}}</button></div><div class="banner-state" role="status" aria-live="polite">{{saving?'正在保存…':notice||'记录你的观影选择'}}</div><p v-if="actionError" role="alert" class="action-error">{{actionError}} <button class="textlink" :disabled="saving" @click="refreshState">刷新状态</button></p></div></div></section>
<div class="container content"><main class="main"><section class="section"><h2>剧情简介</h2><p class="overview">{{movie.overview||'暂无剧情简介。'}}</p></section><section class="section"><div class="section-heading"><h2>演员阵容</h2><a v-if="tmdbCastUrl" class="cast-more" :href="tmdbCastUrl" target="_blank" rel="noopener">查看更多 →</a></div><div v-if="visibleCredits.length" class="cast-strip" tabindex="0" role="group" aria-label="演员阵容，横向滚动查看"><article v-for="c in visibleCredits" :key="c.credit_id" class="credit"><img v-if="photo(c)&&!photoFailures[photoKey(c)]" class="credit-photo" :src="photo(c)" :alt="c.name+'照片'" loading="lazy" @error="photoFailures[photoKey(c)]=true"/><span v-else class="avatar" :aria-label="c.name+'暂无照片'" role="img">{{c.name.slice(0,1)}}</span><b>{{c.name}}</b><small>{{c.character_name||(c.role_type==='crew'?'导演':'演员')}}</small></article><a v-if="tmdbCastUrl" class="cast-full" :href="tmdbCastUrl" target="_blank" rel="noopener">完整演职员表</a></div><p v-else class="muted">演职员资料暂未提供。</p><p v-if="missingPhotos" class="muted">展示的 {{missingPhotos}} 位演职人员暂无可用照片，姓名与职务仍可查看。</p></section><section class="section"><div class="section-heading"><h2>继续探索</h2><span class="muted">本地推荐</span></div><div v-for="m in recommendations" :key="m.movie_id" class="recommend"><button v-if="movieArtwork[String(m.movie_id)]" class="recommend-poster" :aria-label="'查看'+m.title+'海报详情'" @click="openMovie(m.movie_id)"><img :src="movieArtwork[String(m.movie_id)]!.poster" :alt="m.title+'海报'" loading="lazy"/></button><div><b>{{m.title}}</b><small>{{m.reasons?.join('；')}}</small><button :aria-label="'查看'+m.title+'详情'" @click="openMovie(m.movie_id)">查看电影信息</button></div></div><p v-if="!recommendations.length" class="muted">暂无推荐候选。</p></section><section class="section"><h2>来源评分</h2><div v-for="r in sourceRatings" :key="r.source" class="info-row"><span>{{r.source}}</span><strong>{{r.score_value??'暂无'}} / {{r.score_scale}}<small class="score-sub"> · {{r.vote_count??'未知'}} 票</small></strong></div><p v-if="!sourceRatings.length" class="muted">暂无来源评分。</p></section></main><aside class="facts-sidebar"><section class="section"><h2>影片信息</h2><div class="info-row"><span>上映年份</span><strong>{{movie.release_year||'未知'}}</strong></div><div class="info-row"><span>片长</span><strong>{{movie.runtime_minutes?movie.runtime_minutes+' 分钟':'未知'}}</strong></div><div class="info-row"><span>原始语言</span><strong>{{movie.original_language||'未知'}}</strong></div><div class="info-row"><span>类型</span><strong>{{genreText||'待补充'}}</strong></div><div class="info-row"><span>制作国家</span><strong>{{countries.length?countries.map((c:string)=>countryName(c)).join(' / '):'未知'}}</strong></div><div v-for="x in movie.external_ids" :key="x.source" class="info-row"><span>{{x.source}} ID</span><strong>{{x.external_id}}</strong></div></section><section class="section"><h2>我的评分</h2><div class="score-stats"><div class="score-value">{{state.rating??'—'}}</div><div class="score-sub">满分 5 星<br/>你的个人评分</div></div><div class="stars" role="group" aria-label="快捷评分"><button v-for="n in 5" :key="n" class="star" :class="{active:Number(state.rating)>=n}" :aria-label="n+'星'" :disabled="saving||!behaviorReady" @click="act('rating',false,n)"><svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="m12 2 3 6.5 7 1-5 5 1.2 7L12 18l-6.2 3.5 1.2-7-5-5 7-1Z"/></svg></button></div><form class="rating-form" @submit.prevent="act('rating',false,Number(rating))"><label>精确评分<select v-model="rating" :disabled="saving||!behaviorReady"><option v-for="n in 10" :key="n" :value="String(n/2)">{{n/2}} 星</option></select></label><button class="btn" :disabled="saving||!behaviorReady">保存评分</button></form><div class="mini-links"><button class="textlink" :disabled="saving||!behaviorReady||!state.rating" @click="act('rating',true)">清除我的评分</button></div></section></aside></div><footer class="container footer">电影资料来自已授权静态 TMDB 副本。This product uses the TMDB API but is not endorsed or certified by TMDB. <a href="https://www.themoviedb.org/" target="_blank" rel="noopener">TMDB</a></footer></template>
</div></div>
